#include <vector>

class Solution {
public:
    int findLatestStep(std::vector<int>& arr, int m) {
        int n = arr.size();
        if (m == n) return n;
        std::vector<int> length(n + 2, 0);
        std::vector<int> count(n + 1, 0);
        int ans = -1;
        for (int step = 1; step <= n; ++step) {
            int x = arr[step - 1];
            int left = length[x - 1], right = length[x + 1];
            int newLen = left + right + 1;
            length[x - left] = newLen;
            length[x + right] = newLen;
            count[left]--;
            count[right]--;
            count[newLen]++;
            if (count[m] > 0) ans = step;
        }
        return ans;
    }
};

